import axios from "axios";

// ✅ Ensure the API base URL exists
const BASE_URL = import.meta.env.VITE_API_BASE_URL;

if (!BASE_URL) {
  console.error(
    "❌ VITE_API_BASE_URL is undefined. Make sure you have a .env file in the frontend root with VITE_API_BASE_URL set."
  );
}

// Create an Axios instance with base URL
const api = axios.create({
  baseURL: BASE_URL || "http://localhost:5000/api", // fallback just in case
  headers: {
    "Content-Type": "application/json",
  },
});

// Add JWT token automatically if present
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Debug log
console.log("API base URL:", BASE_URL);

export default api;
